SELECT a.ENDDATE AS `截止日期`, a.STOCKSNAME AS `股票名称`, a.STOCKCODE AS `股票代码`, ROUND(a.TCLOSE, 2) AS `收盘价(元)`, ROUND(a.CHNG_PCT_TMONTH, 2) AS `2026年7月月度涨跌幅(%)` FROM ANA_STK_EXPR_IDX a JOIN GET_A_SEC_CODE b ON a.INNER_CODE = b.INNER_CODE WHERE a.STOCKSNAME LIKE '%格力电器%' AND a.ENDDATE >= '2026-07-01' AND a.ENDDATE <= '2026-07-31' AND a.CHNG_PCT_TMONTH IS NOT NULL AND a.TCLOSE IS NOT NULL AND b.ISVALID = 1 ORDER BY a.ENDDATE DESC LIMIT 1;
